insert into public.pages (slug, title, content, hero_image_url, sections)
values
('home', 'Engineers Without Borders Kenya Community', '<p class="text-lg"><strong>Engineers Without Borders Kenya Community</strong> (EWB KeC) is a volunteer-driven group of engineers and professionals creating sustainable engineering solutions that improve quality of life across Kenya. We focus on water access, sanitation, renewable energy, and resilient infrastructure—delivered with a community-centric approach and strong partnerships.</p><h2 class="mt-6 text-2xl font-semibold">Vision</h2><p>A future where sustainable engineering solutions empower communities, improve quality of life, and drive equitable development across Kenya.</p><h2 class="mt-6 text-2xl font-semibold">Mission</h2><p>We harness volunteer engineering skills to design and implement sustainable solutions that address local challenges, improve community well-being, and foster resilience—through collaboration, mentorship, and innovation.</p><h3 class="mt-6 text-xl font-semibold">What we do</h3><ul class="list-disc ml-6 space-y-1"><li>Community-centric projects in water, sanitation, renewable energy, and infrastructure</li><li>Mentorship for engineers and youth (hands-on STEM activities, capacity building)</li><li>Partnerships with NGOs, agencies, academia, and local stakeholders</li><li>Evidence-based advocacy and policy influence</li></ul><h3 class="mt-6 text-xl font-semibold">2024 at a glance</h3><ul class="list-disc ml-6 space-y-1"><li>124+ members and growing</li><li>Site visits & needs assessments in Amboseli & schools</li><li>Workshops and mentorship events</li></ul><div class="mt-6 p-4 rounded-xl" style="background:#F3F4F6"><h3 className="text-xl font-semibold">How you can help</h3><p>Donate, volunteer, or spread the word. Contact: <a href="mailto:ewbkenyacommunity@gmail.com">ewbkenyacommunity@gmail.com</a></p></div><p class="mt-6 text-sm opacity-80">#SmallChangesBigImpact</p>', null, '[]'::jsonb)
